import "server-only";

import type { SongScores } from "@gt/domain/audio.yue2";
import { ok, type Result } from "@gt/domain/errors";
import { putSongScores as putRows, songScoresFor } from "@gt/kernel/library/songScores";
import type { Store } from "@gt/kernel/store";

// A TAKE'S SONG SCORES (spark yue2-song-lab, WP2): the DERIVED kernel table `audio_song_scores`
// (packages/kernel/src/library/songScores.ts), keyed (sha, scorer_version), regenerated by the
// `yue2-score` producer (WP3) and seeded once by the backfill import (pipeline/yue2/import.mts).
// LUFS / true peak are not here: they are `audio_measures` (the media-facts pass).

/** The newest-scorer row per sha; a sha never scored is absent. */
export function readSongScores(store: Store, shas: readonly string[]): Result<Readonly<Record<string, SongScores>>> {
  return songScoresFor(store, shas);
}

/** Write one row (replaces the row of the same sha and scorer version). */
export function putSongScores(store: Store, row: SongScores): Result<SongScores> {
  const put = putRows(store, [row]);
  return put.ok ? ok(row) : put;
}
